/** KaTeX label embedding: measurement + <foreignObject> markup generation. */

export interface KatexLike {
  renderToString(tex: string, options?: Record<string, unknown>): string;
}

export interface LabelSize {
  width: number;
  height: number;
}

export interface LabelMeasurer {
  measure(tex: string, fontSizePx: number): LabelSize;
}

/** Locate KaTeX: explicit config → global. */
export function resolveKatex(explicit?: KatexLike | null): KatexLike | undefined {
  if (explicit) return explicit;
  if (explicit === null) return undefined;
  const g = globalThis as { katex?: KatexLike };
  return g.katex && typeof g.katex.renderToString === 'function' ? g.katex : undefined;
}

/**
 * Browser measurer: renders KaTeX into a hidden element and reads the real
 * box. Results are cached per (tex, fontSize).
 */
export class DomLabelMeasurer implements LabelMeasurer {
  private host: HTMLElement | null = null;
  private readonly cache = new Map<string, LabelSize>();

  constructor(private readonly katex: KatexLike) {}

  private ensureHost(): HTMLElement | null {
    if (typeof document === 'undefined') return null;
    if (this.host && this.host.isConnected) return this.host;
    const el = document.createElement('div');
    el.setAttribute('aria-hidden', 'true');
    el.style.cssText =
      'position:absolute;left:-99999px;top:0;visibility:hidden;pointer-events:none;white-space:nowrap;';
    document.body.appendChild(el);
    this.host = el;
    return el;
  }

  measure(tex: string, fontSizePx: number): LabelSize {
    const key = `${fontSizePx}�${tex}`;
    const hit = this.cache.get(key);
    if (hit) return hit;
    const host = this.ensureHost();
    if (!host) return heuristicSize(tex, fontSizePx);
    let size: LabelSize;
    try {
      host.style.fontSize = `${fontSizePx}px`;
      host.innerHTML = this.katex.renderToString(tex, { throwOnError: false });
      const rect = host.getBoundingClientRect();
      size =
        rect.width > 0 && rect.height > 0
          ? { width: rect.width, height: rect.height }
          : heuristicSize(tex, fontSizePx);
    } catch {
      size = heuristicSize(tex, fontSizePx);
    }
    this.cache.set(key, size);
    return size;
  }
}

/** Font-metric estimate for environments without layout (tests, SSR). */
export function heuristicSize(tex: string, fontSizePx: number): LabelSize {
  const stripped = tex
    .replace(/\\[a-zA-Z]+/g, 'M') // each command ≈ one glyph
    .replace(/[{}^_\s]/g, '');
  const chars = Math.max(1, stripped.length);
  const tall = /[\^_]|\\frac|\\bar|\\hat|\\tilde/.test(tex);
  return { width: 0.62 * fontSizePx * chars + 4, height: (tall ? 1.55 : 1.25) * fontSizePx };
}

export class HeuristicLabelMeasurer implements LabelMeasurer {
  measure(tex: string, fontSizePx: number): LabelSize {
    return heuristicSize(tex, fontSizePx);
  }
}

const XML_ESCAPES: Record<string, string> = {
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;',
};

export function escapeXml(s: string): string {
  return s.replace(/[&<>"']/g, (c) => XML_ESCAPES[c]!);
}

const fmt = (n: number): string => {
  const r = Math.round(n * 100) / 100;
  return Object.is(r, -0) ? '0' : String(r);
};

/**
 * SVG fragment for one label centered at (cx, cy). Uses a <foreignObject>
 * with KaTeX HTML when available, else a plain <text> fallback (raw TeX,
 * italic serif) so the diagram degrades gracefully without KaTeX.
 */
export function labelMarkup(
  tex: string,
  cx: number,
  cy: number,
  size: LabelSize,
  fontSizePx: number,
  katex: KatexLike | undefined,
  cssClass = 'fm-label',
): string {
  if (katex) {
    let html: string;
    try {
      html = katex.renderToString(tex, { throwOnError: false });
    } catch {
      html = escapeXml(tex);
    }
    // Padding absorbs italic overhang that getBoundingClientRect misses.
    const pad = 0.2 * fontSizePx;
    const w = size.width + 2 * pad;
    const h = size.height + 2 * pad;
    return (
      `<foreignObject x="${fmt(cx - w / 2)}" y="${fmt(cy - h / 2)}" width="${fmt(w)}" height="${fmt(h)}" ` +
      `overflow="visible">` +
      `<div xmlns="http://www.w3.org/1999/xhtml" class="${cssClass}" ` +
      `style="display:flex;align-items:center;justify-content:center;width:100%;height:100%;` +
      `font-size:${fmt(fontSizePx)}px;line-height:1;color:inherit;">` +
      html +
      `</div>` +
      `</foreignObject>`
    );
  }
  return (
    `<text class="${cssClass}" x="${fmt(cx)}" y="${fmt(cy)}" text-anchor="middle" dominant-baseline="central" ` +
    `style="font:italic ${fmt(fontSizePx)}px Georgia,'Times New Roman',serif;fill:currentColor;stroke:none"` +
    `>${escapeXml(tex)}</text>`
  );
}
