import type { DiagramModel, Edge } from '../model/model';
import { arcBetween, dist, loopAt, norm, sub, type Path, type Vec2 } from './geometry';
import type { VertexLayout } from './layout';

export interface EdgeGeometry {
  edge: Edge;
  path: Path;
}

const LOOP_RADIUS_FACTOR = 0.42;

/**
 * Turn each edge into a concrete Path: apply explicit bends, fan out parallel
 * edges that have no explicit bend, and attach tadpole loops.
 */
export function buildEdgeGeometries(model: DiagramModel, layout: VertexLayout): EdgeGeometry[] {
  const pos = layout.positions;

  // Group parallel (non-loop) edges by unordered vertex pair.
  const groups = new Map<string, Edge[]>();
  for (const e of model.edges) {
    if (e.from === e.to) continue;
    const key = e.from < e.to ? `${e.from}�${e.to}` : `${e.to}�${e.from}`;
    const g = groups.get(key);
    if (g) g.push(e);
    else groups.set(key, [e]);
  }

  // Auto-fan: assign symmetric bends to groups where no edge has an explicit bend.
  const autoBend = new Map<number, number>();
  for (const g of groups.values()) {
    if (g.length < 2 || g.some((e) => e.bend !== undefined)) continue;
    const canonical = g[0]!.from < g[0]!.to ? g[0]!.from : g[0]!.to;
    const beta = Math.min(80, 40 + 10 * (g.length - 2));
    for (let i = 0; i < g.length; i++) {
      // Geometric bend relative to the canonical direction, from +beta to -beta.
      const gBend = g.length === 1 ? 0 : beta - (2 * beta * i) / (g.length - 1);
      const e = g[i]!;
      autoBend.set(e.index, e.from === canonical ? gBend : -gBend);
    }
  }

  // Loop direction bookkeeping: cycle fallback directions per vertex.
  const loopDirsUsed = new Map<string, number>();

  const geoms: EdgeGeometry[] = [];
  for (const e of model.edges) {
    if (e.from === e.to) {
      geoms.push({ edge: e, path: tadpolePath(model, e, pos, layout.unit, loopDirsUsed) });
      continue;
    }
    const a = pos.get(e.from)!;
    const b = pos.get(e.to)!;
    const bend = e.bend ?? autoBend.get(e.index) ?? 0;
    geoms.push({ edge: e, path: arcBetween(a, b, bend) });
  }
  return geoms;
}

const DIR_VECS: Record<string, Vec2> = {
  up: { x: 0, y: -1 },
  down: { x: 0, y: 1 },
  left: { x: -1, y: 0 },
  right: { x: 1, y: 0 },
};

function tadpolePath(
  model: DiagramModel,
  e: Edge,
  pos: Map<string, Vec2>,
  unit: number,
  used: Map<string, number>,
): Path {
  const v = pos.get(e.from)!;
  let dir: Vec2 | undefined;
  if (e.loop && e.loop !== 'auto') dir = DIR_VECS[e.loop];

  if (!dir) {
    // Away from the mean direction of the other neighbors.
    let dx = 0;
    let dy = 0;
    for (const other of model.edges) {
      if (other.from === other.to) continue;
      const nb = other.from === e.from ? other.to : other.to === e.from ? other.from : undefined;
      if (!nb) continue;
      const q = pos.get(nb)!;
      const u = norm(sub(q, v));
      dx += u.x;
      dy += u.y;
    }
    const l = Math.hypot(dx, dy);
    dir = l > 1e-9 ? { x: -dx / l, y: -dy / l } : { x: 0, y: -1 };
    // Several auto loops on one vertex: rotate successive loops 90° apart.
    const k = used.get(e.from) ?? 0;
    if (k > 0) {
      const ang = (k * Math.PI) / 2;
      const c = Math.cos(ang);
      const s = Math.sin(ang);
      dir = { x: dir.x * c - dir.y * s, y: dir.x * s + dir.y * c };
    }
  }
  used.set(e.from, (used.get(e.from) ?? 0) + 1);

  const radius = LOOP_RADIUS_FACTOR * unit;
  return loopAt(v, dir, radius);
}

/** Mean non-loop chord length in px (used to size loop radii, nudges…). */
export function meanEdgeLength(model: DiagramModel, pos: Map<string, Vec2>): number {
  const ls: number[] = [];
  for (const e of model.edges) {
    if (e.from === e.to) continue;
    ls.push(dist(pos.get(e.from)!, pos.get(e.to)!));
  }
  return ls.length ? ls.reduce((a, b) => a + b, 0) / ls.length : 0;
}
